import '@/services/browser-support/modern-build-guard';
import '@/services/sentry/sentry-start';
// Language polyfills are generated by Vite for the supported browser targets.
import { mount } from 'svelte';
import App from '@/App.svelte';
import { loadGameAssetOrigin } from '@/lib/assets/game-assets';
import { initializeTheme } from '@/stores/theme';
import { initializeWorkspace } from '@/lib/workspaces/workspace-state';
import { initializeAuth } from '@/services/auth/auth-state';
import '@/styles/global.css';

if (!('popover' in HTMLElement.prototype)) await import('@oddbird/popover-polyfill');

document.documentElement.dataset.appPhase = 'mounting';
initializeTheme();
initializeWorkspace();
// The callback owns session verification; an old stored session must not race it.
if (location.pathname !== '/signin' || !new URLSearchParams(location.search).get('token'))
  void initializeAuth();

const target = document.getElementById('app');
if (!target) throw new Error('The application mount point is missing.');

// Artwork URLs come from the published asset manifest, so it has to land before the first render.
// It falls back to the local copy on its own, and never waits longer than its own timeout.
await loadGameAssetOrigin();

mount(App, { target });
document.documentElement.dataset.appPhase = 'mounted';
document.getElementById('seo-content')?.remove();
